"""Playback markers acknowledged before a barge-in."""

from enum import Enum
from typing import Any, Dict, Final, List, Optional

from pydantic import BaseModel, ConfigDict, Field, ValidationError

# Shared reads these keys and cannot import the composer, which writes them.
BARGE_IN_PLAYBACK_METADATA_KEY: Final = "playback"
ACKNOWLEDGED_INTERMEDIATE_MARKERS_METADATA_KEY: Final = (
    "acknowledged_intermediate_markers"
)


class PlaybackPositionKind(str, Enum):
    WORD = "word"
    AUDIO_ELAPSED = "audio_elapsed"


class PlaybackPosition(BaseModel):
    """Where playback had reached when an intermediate marker was sent."""

    model_config = ConfigDict(frozen=True)
    kind: PlaybackPositionKind
    offset_ms: int
    word_index: Optional[int] = None
    start_ms: Optional[int] = None
    timing_source: Optional[str] = None

    @classmethod
    def from_dict(cls, raw_marker: object) -> Optional["PlaybackPosition"]:
        """Return the position, or None when the payload does not match its shape."""
        if not isinstance(raw_marker, dict):
            return None
        try:
            return cls.model_validate(raw_marker)
        except ValidationError:
            return None

    def as_metadata(self) -> Dict[str, Any]:
        """Return the position stored on a barge-in event."""
        return self.model_dump(exclude_none=True)


class PlaybackMarkers(BaseModel):
    """Acknowledged playback positions for one interrupted response."""

    model_config = ConfigDict(frozen=True)

    markers: List[PlaybackPosition] = Field(default_factory=list)

    @classmethod
    def from_metadata(cls, metadata: Optional[Dict[str, Any]]) -> "PlaybackMarkers":
        """Read markers from a barge-in event's metadata."""
        playback = (metadata or {}).get(BARGE_IN_PLAYBACK_METADATA_KEY)
        if not isinstance(playback, dict):
            return cls()
        return cls.from_dicts(
            playback.get(ACKNOWLEDGED_INTERMEDIATE_MARKERS_METADATA_KEY)
        )

    @classmethod
    def from_dicts(cls, raw_markers: object) -> "PlaybackMarkers":
        """Keep marker dicts that match the playback marker shape."""
        if not isinstance(raw_markers, list):
            return cls()
        parsed = (PlaybackPosition.from_dict(raw_marker) for raw_marker in raw_markers)
        return cls(markers=[marker for marker in parsed if marker is not None])

    def confirmed_word_index(self) -> Optional[int]:
        """Return the last word marker's index into the reply.

        Elapsed markers fill pauses between words, so the last marker overall
        can be an elapsed one even though a word was confirmed just before it.
        """
        for marker in reversed(self.markers):
            if marker.kind != "word" or marker.word_index is None:
                continue
            return marker.word_index
        return None

    def elapsed_cutoff(self) -> Optional[str]:
        """Return the last marker's audio time when no word index was confirmed."""
        if not self.markers:
            return None
        return f"{self.markers[-1].offset_ms / 1000:.1f} seconds of playback"
